mapper.select:
SELECT m.*
FROM t_ai_message m
JOIN t_ai_conversation c ON c.id = m.conversation_id
WHERE m.conversation_id = #{conversationId}
  AND m.message_no = #{messageNo}
  AND m.role = 'USER'
  AND m.status = 'ACTIVE'
  AND c.user_id = #{userId}

mapper.update:
UPDATE t_ai_message
SET status = 'SUPERSEDED',
    included_in_context = FALSE,
    version = version + 1,
    edit_time = CURRENT_TIMESTAMP,
    edit_by = #{editBy}
WHERE id = #{id}
  AND status = 'ACTIVE'
  AND version = #{expectedVersion}

UPDATE t_ai_message
SET status = 'WITHDRAWN',
    included_in_context = FALSE,
    version = version + 1,
    withdrawn_time = CURRENT_TIMESTAMP,
    withdrawn_by = #{withdrawnBy}
WHERE id = #{id}
  AND status = 'ACTIVE'
  AND version = #{expectedVersion}

UPDATE t_ai_message
SET included_in_context = FALSE,
    edit_time = CURRENT_TIMESTAMP,
    edit_by = #{editBy}
WHERE conversation_id = #{conversationId}
  AND run_id IN (
      SELECT id FROM t_ai_run
      WHERE conversation_id = #{conversationId}
        AND turn_no >= #{turnNo}
  )
